package org.javaboy.vhr.controller.personnel;import org.javaboy.vhr.framework.entity.RespBean;import org.javaboy.vhr.system.entity.Employeeremove;import org.javaboy.vhr.system.service.IEmployeeremoveService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/personnel/remove") public class EmployeeMoveController{private final IEmployeeremoveService service;public EmployeeMoveController(IEmployeeremoveService s){service=s;}@GetMapping public Object list(){return service.list();}@PostMapping public RespBean add(@RequestBody Employeeremove x){return service.save(x)?RespBean.ok("新增成功",x):RespBean.error("新增失败");}@PutMapping public RespBean update(@RequestBody Employeeremove x){return service.updateById(x)?RespBean.ok("更新成功"):RespBean.error("更新失败");}@DeleteMapping("/{id}") public RespBean delete(@PathVariable Integer id){return service.removeById(id)?RespBean.ok("删除成功"):RespBean.error("删除失败");}}
